#include "maze3d.h"

// v6.7-beta: 8x8 单色贴图, tx=0 对应字节的 bit 0 (LSB=最左像素), 共8字节/贴图
// 像素风但更真实: 不密集填充, 留白多, 线条干净, 便于以后扩展更复杂纹理
// 0-11: 已用 (对应枚举 CellType 的 WALL_* 顺序)
// 12-23: 空白保留 (全0), 给未来方块:
// 圆石/煤/铁/钻石/台阶/玻璃/工作台/熔炉/羊毛/苔石/地狱岩/末地石
const uint8_t TEXTURES[TEX_COUNT][8] = {
    // ---- [0] 砖墙 Bricks ---- 错缝砌法, 砂浆缝干净留白
    {0xFF, 0x81, 0x7B, 0x7B, 0xFF, 0xDB, 0xDE, 0xDE},

    // ---- [1] 石墙 Stone/Cobble ---- 圆润卵石, 大块留白作阴影
    {0x3C, 0x7E, 0xC3, 0x81, 0x7E, 0x81, 0x3C, 0x24},

    // ---- [2] 金属墙 Metal ---- 嵌板+四角铆钉, 中部大块留白显干净
    {0x81, 0x7E, 0x42, 0x3C, 0x3C, 0x42, 0x7E, 0x81},

    // ---- [3] 藤蔓 Vine ---- 有机叶须, 大量留白作空隙
    {0x24, 0x18, 0x5A, 0x24, 0x66, 0x18, 0x42, 0x24},

    // ---- [4] 水 Water (动态) ---- 宽波峰+波谷留白, 非密集
    {0x00, 0x18, 0x3C, 0x00, 0x3C, 0x18, 0x00, 0x66},

    // ---- [5] 草方块侧面 Grass side ---- 上2行纯草层, 下6行土+散根, 大量留白
    {0xFF, 0xFF, 0x92, 0x44, 0x28, 0x10, 0x44, 0x28},

    // ---- [6] 木板 Planks ---- 3条垂直木板 + 横纹接缝, 干净留白
    {0xDB, 0x99, 0xDB, 0xFF, 0xDB, 0x99, 0xDB, 0xFF},

    // ---- [7] 树叶 Leaves ---- 不规则团叶, 大量留白作叶间空隙 (真实树叶非满)
    {0x24, 0x66, 0x7E, 0x99, 0x3C, 0x66, 0x24, 0x18},

    // ---- [8] 沙子 Sand ---- 均匀细颗粒, 点与点之间全留白
    {0x11, 0x44, 0x02, 0x88, 0x22, 0x08, 0x41, 0x14},

    // ---- [9] 土 Dirt ---- 比沙更大颗粒, 不规则团, 留白更多
    {0x44, 0x00, 0x82, 0x10, 0x44, 0x28, 0x00, 0x82},

    // ---- [10] 原木侧面 Log side ---- 粗树皮竖纹, 间中留白作皮裂
    {0x81, 0x42, 0x3C, 0x81, 0x42, 0x3C, 0x81, 0x42},

    // ---- [11] 光柱/太阳 Light column ---- 上窄下宽, 简洁光束
    {0x18, 0x18, 0x3C, 0x3C, 0x7E, 0x7E, 0xFF, 0xFF},

    // ============================================================
    // [12..23] 空白保留槽 — 未来方块类型, 全 0 = 完全空白贴图
    // 未来候选: 圆石, 煤矿, 铁矿, 钻石, 台阶, 玻璃, 工作台, 熔炉, 羊毛, 苔石,
    // 地狱岩, 末地石
    // ============================================================
    {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00}, // 12: 预留 (圆石 Cobblestone)
    {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00}, // 13: 预留 (煤矿 Coal Ore)
    {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00}, // 14: 预留 (铁矿 Iron Ore)
    {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00}, // 15: 预留 (钻石 Diamond Ore)
    {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00}, // 16: 预留 (台阶 Stairs)
    {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00}, // 17: 预留 (玻璃 Glass)
    {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00}, // 18: 预留 (工作台 Crafting Table)
    {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00}, // 19: 预留 (熔炉 Furnace)
    {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00}, // 20: 预留 (羊毛 Wool)
    {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00}, // 21: 预留 (苔石 Mossy Cobble)
    {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00}, // 22: 预留 (地狱岩 Netherrack)
    {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00}, // 23: 预留 (末地石 End Stone)
};

// v6.7-beta: 取贴图像素. 水(tex_id==4)按 g.tick 做垂直流动偏移.
// 保留槽位 (>=12) 直接返回 0 (=空白/全透明像素), 以后填纹理就自动有内容了.
uint8_t texture_sample(int tex_id, int tx, int ty) {
    if(tex_id < 0 || tex_id >= TEX_COUNT) return 1;
    // 预留空白槽位: 直接返回 0 (完全空), 防止越界读也避免默认亮
    if(tex_id >= 12) return 0;
    tx &= 7;
    ty &= 7;
    // 水流动 — ty 按 tick 缓慢偏移, 产生波纹滚动效果
    if(tex_id == 4) {
        ty = (ty + (uint8_t)(g.tick >> 2)) & 7;
    }
    return (TEXTURES[tex_id][ty] >> (tx & 7)) & 1;
}
